g.onclick:
var parent = document.getElementById('Layer_Plays');
var children = Array.from(parent.children).filter(c => c.tagName === 'g');
var currentIndex = children.findIndex(c => c.style.display !== 'none');

// Hide current
if (currentIndex !== -1) {
    children[currentIndex].style.display = 'none';
}

// Calculate next (loop back to 0 if at the end)
var nextIndex = (currentIndex - 1 + children.length) % children.length;

// Show next
children[nextIndex].style.display = 'inline';

var parent = document.getElementById('Layer_Plays');
var children = Array.from(parent.children).filter(c => c.tagName === 'g');
var currentIndex = children.findIndex(c => c.style.display !== 'none');

// Hide current
if (currentIndex !== -1) {
    children[currentIndex].style.display = 'none';
}

// Calculate next (loop back to 0 if at the end)
var nextIndex = (currentIndex + 1) % children.length;

// Show next
children[nextIndex].style.display = 'inline';

svg.script:
function init(evt) {
	const ThibaultEditor = {
		// 1. App State
		isEditMode: false,
		selectedGroup: null,
		activeAction: null, // 'drag' or 'rotate'
		svg: null,


		// 2. Transformation State (The coordinates you wanted to move)
		transformState: {
			x: 0,
			y: 0,
			rot: 0,
			offset: { x: 0, y: 0 }
		},

		// 3. UI Toggle
		toggleEditMode: function(editBtn) {
			this.isEditMode = !this.isEditMode;
			label = document.getElementById('coord_output');

			if (this.isEditMode) {
				editBtn.style.fill = '#ea28f0'; 
				label.style.display = 'inline';
			} else {
				editBtn.style.fill = '#f9f9f9'; 

				this.selectedGroup = null;
				label.style.display = 'none';
				label.textContent = "Selection: None | Pos: (0,0) | Rot: 0°";
			}
		},


		// 4. Mouse Logic
		handleMouseDown: function(e){
			// ONLY proceed if edit mode is active
			if (!this.isEditMode) return;

			const path = e.target.closest('#Layer_Plays path');
			const handle = e.target.closest('.rotate-handle');

			if (path) {			
				// Select new
				this.selectedGroup = path;

				this.activeAction = 'drag';
				const mouse = this.getMousePos(e);
				// 1. Access the browser's already-parsed transform list for the element
				const transformList = this.selectedGroup.transform.baseVal;

				let matrix;
				if (transformList.numberOfItems > 0) {
					// 2. Consolidate all transforms (translate, rotate, etc.) into one matrix
					matrix = transformList.consolidate().matrix;
				} else {
					// 3. Fallback to an identity matrix if no transform exists
					matrix = svg.createSVGMatrix(); 
				}
				this.transformState.x = matrix.e;
				this.transformState.y = matrix.f;
				this.transformState.offset.x = mouse.x - matrix.e;
				this.transformState.offset.y = mouse.y - matrix.f;

			} else if (handle && this.selectedGroup) {
				this.activeAction = 'rotate';
			}
		},

		handleMouseMove: function(e) {
			if (!this.activeAction || !this.selectedGroup) return;
			const mouse = this.getMousePos(e);

			if (this.activeAction === 'drag') {
				this.transformState.x = mouse.x - this.transformState.offset.x;
				this.transformState.y = mouse.y - this.transformState.offset.y;
			} else if (this.activeAction === 'rotate') {
				let angle = Math.atan2(mouse.y - this.transformState.y, mouse.x - this.transformState.x) * (180 / Math.PI) + 90;
				if (isSnapEnabled) angle = Math.round(angle / 15) * 15;
				this.transformState.rot = angle;
			}

			this.selectedGroup.setAttribute('transform', `translate(${this.transformState.x}, ${this.transformState.y}) rotate(${this.transformState.rot})`);
			const label = document.getElementById('coord_output');
			label.textContent = "Selection: " + this.selectedGroup.getAttribute("inkscape:label") + 
					" | Pos: (" + Math.round(this.transformState.x) + "," + Math.round(this.transformState.y) + 
					") | Rot: " + Math.round(this.transformState.rot) + "°";
		},

		handleMouseUp: function(e) {
			this.activeAction = null;
		},

		getMousePos: function(evt) {
			const CTM = this.svg.getScreenCTM();
			return { x: (evt.clientX - CTM.e) / CTM.a, y: (evt.clientY - CTM.f) / CTM.d };
		},
	};

    ThibaultEditor.svg = evt.target;
	window.ThibaultEditor = ThibaultEditor;

    // Global SVG listeners for dragging
	ThibaultEditor.svg.addEventListener('mousedown', ThibaultEditor.handleMouseDown.bind(ThibaultEditor));
    window.addEventListener('mousemove', ThibaultEditor.handleMouseMove.bind(ThibaultEditor));
    window.addEventListener('mouseup', ThibaultEditor.handleMouseUp.bind(ThibaultEditor));
};
